WITH recent_suppliers AS (SELECT * FROM suppliers WHERE rating > 3.0), Agg AS (SELECT CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, city, ROUND(STDDEV(rating), 2) AS stddev_rating FROM recent_suppliers GROUP BY CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END, city) SELECT * FROM Agg WHERE stddev_rating > 33 ORDER BY rating_bucket DESC, stddev_rating DESC, city LIMIT 5;
